import axios from 'axios';
import { defineStore } from 'pinia';
import { DOC2API_URL } from 'src/pages/APIs';
import { termAndConditionApiService } from 'src/services';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { ref } from 'vue';

export const useTermAndCondtionStore = defineStore('term_and_condtion', {
  state: () => ({
    loading: false,
    url: ref(''),
  }),
  getters: {},
  actions: {
    async uploadTerm(file: any): Promise<void> {
      this.loading = true;
      try {
        await termAndConditionApiService.upload(file);
        await this.getFile();
        this.loading = false;
      } catch (error) {
        logInfo(error, 'error');
      }
    },
    async getFile() {
      try {
        const org_id = getOrgId();
        if (org_id) {
          const response = await axios.get(
            `${DOC2API_URL}/supplier/get_terms_and_conditions?org_id=${org_id}`,
            {
              responseType: 'blob',
            },
          );
          if (response) {
            const contentType = response.headers['content-type'];
            const isJson =
              contentType && contentType.includes('application/json');

            if (isJson) {
              const text = await response.data.text();
              if (text) {
                const data = JSON.parse(text);

                if (data.success === false) {
                  return;
                }
              }
            } else {
              this.url = window.URL.createObjectURL(response.data);
            }
          }
        }
      } catch (error) {
        logError('Failed to fetch file:', error);
      }
    },
  },
});
